INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(539187, 54374, 772, '<td valign="top">great idea here but it''s a bit too soft overall...</td>', 'great idea here but it''s a bit too soft overall...', '2004-01-12 00:03:49.000000', NULL, 1),
(539191, 54688, 3102, '<td valign="top">Great!  Nice, spooky feel to it :)</td>', 'Great!  Nice, spooky feel to it :)', '2004-01-12 00:08:04.000000', NULL, 1),
(539192, 54744, 3102, '<td valign="top">Very nicely done!  I like the "winter wonderland" feel of it.</td>', 'Very nicely done!  I like the "winter wonderland" feel of it.', '2004-01-12 00:08:43.000000', NULL, 1),
(539195, 54688, 2125, '<td valign="top">1st place according to my daughter and me 10+</td>', '1st place according to my daughter and me 10+', '2004-01-12 00:12:42.000000', NULL, 1),
(539196, 54764, 6008, '<td valign="top">The clouds are good, the power lines have good leading lines, but the picture is badly out of focus.</td>', 'The clouds are good, the power lines have good leading lines, but the picture is badly out of focus.', '2004-01-12 00:13:07.000000', NULL, 1),
(539200, 54117, 6008, '<td valign="top">I''m not sure if this is IR or just post processing. The top of the mosque looks good, the color seems to fit and contrasts nicely against the blue. Also fairly sharp. Unfortunately it''s the lower part of the photograph I''m not too fond of. The tree on the left looks like it''s been badly masked with the pink at the top and the white through the branches. The middle tree has an unnatural-looking hue, and the pink in the sky surrounding that tree also seems quite unnatural. It may have appeal to some people, but it just looks odd to me, sorry.</td>', 'I''m not sure if this is IR or just post processing. The top of the mosque looks good, the color seems to fit and contrasts nicely against the blue. Also fairly sharp. Unfortunately it''s the lower part of the photograph I''m not too fond of. The tree on the left looks like it''s been badly masked with the pink at the top and the white through the branches. The middle tree has an unnatural-looking hue, and the pink in the sky surrounding that tree also seems quite unnatural. It may have appeal to some people, but it just looks odd to me, sorry.', '2004-01-12 00:16:42.000000', NULL, 1),
(539201, 54599, 14608, '<td valign="top">Beautiful colors,very nice shot</td>', 'Beautiful colors,very nice shot', '2004-01-12 00:17:30.000000', NULL, 1),
(539202, 54599, 3102, '<td valign="top">Stunning!  What more can I say...?</td>', 'Stunning!  What more can I say...?', '2004-01-12 00:18:17.000000', NULL, 1),
(539203, 54743, 6008, '<td valign="top">The moon is a little bright but not overly so behind the mass of tree branches. The placement of the moon is good. The branches are not very sharp, and the sky is fairly noisy. Not a bad image, just nothing ''wow'' about it either.</td>', 'The moon is a little bright but not overly so behind the mass of tree branches. The placement of the moon is good. The branches are not very sharp, and the sky is fairly noisy. Not a bad image, just nothing ''wow'' about it either.', '2004-01-12 00:18:24.000000', NULL, 1),
(539205, 54758, 3102, '<td valign="top">I think this might have been a little more effective had something been in sharper focus.  There''s not a lot to see of much interest, I''m afraid.</td>', 'I think this might have been a little more effective had something been in sharper focus.  There''s not a lot to see of much interest, I''m afraid.', '2004-01-12 00:19:30.000000', NULL, 1),
(539207, 54770, 6008, '<td valign="top">This comes across as fairly dark on my monitor. I can see the whole ship, it just blends into the dark sea very well. I mostly see the white shoreline and the part of the ship.</td>', 'This comes across as fairly dark on my monitor. I can see the whole ship, it just blends into the dark sea very well. I mostly see the white shoreline and the part of the ship.', '2004-01-12 00:19:57.000000', NULL, 1),
(539208, 54608, 3102, '<td valign="top">I always enjoy shots where something as simple as a nightlight can be turned into art!  I like what you have done here.</td>', 'I always enjoy shots where something as simple as a nightlight can be turned into art!  I like what you have done here.', '2004-01-12 00:20:21.000000', NULL, 1),
(539209, 54744, 9932, '<td valign="top">Very nice. I would love to have seen more detail pulled out of the shadows. And maybe cut the first light out on the left.</td>', 'Very nice. I would love to have seen more detail pulled out of the shadows. And maybe cut the first light out on the left.', '2004-01-12 00:20:53.000000', NULL, 1),
(539212, 54033, 6008, '<td valign="top">I like this - nice grainy b&amp;w with good contrasts, good leading lines, and has a great atmosphere wih it. Not the usual DPC image, but I hope it does well.</td>', 'I like this - nice grainy b&w with good contrasts, good leading lines, and has a great atmosphere wih it. Not the usual DPC image, but I hope it does well.', '2004-01-12 00:21:33.000000', NULL, 1),
(539215, 54726, 9932, '<td valign="top">I struggled with a similar situation. Nice shot though I feel there could have been more detail in the dock area. Not much for city lights. Nice work.</td>', 'I struggled with a similar situation. Nice shot though I feel there could have been more detail in the dock area. Not much for city lights. Nice work.', '2004-01-12 00:22:47.000000', NULL, 1),
(539217, 54726, 6008, '<td valign="top">It''s a good skyline, nice colors, fairly sharp, although I find the yellow lights in the water a little distracting.</td>', 'It''s a good skyline, nice colors, fairly sharp, although I find the yellow lights in the water a little distracting.', '2004-01-12 00:23:01.000000', NULL, 1),
(539219, 54324, 9932, '<td valign="top">I came very close to doing a similar shot. But it is very hard shooting neon lights after dark. The best time I think is just at sunset to get the true colors and true effects. nice work</td>', 'I came very close to doing a similar shot. But it is very hard shooting neon lights after dark. The best time I think is just at sunset to get the true colors and true effects. nice work', '2004-01-12 00:24:07.000000', NULL, 1),
(539220, 54467, 6008, '<td valign="top">Exposure is good with the flame not blown out. Doesnt really have much ''wow'' factor, though. It could be because it''s a little too centered maybe - it''s just kinda there.</td>', 'Exposure is good with the flame not blown out. Doesnt really have much ''wow'' factor, though. It could be because it''s a little too centered maybe - it''s just kinda there.', '2004-01-12 00:24:17.000000', NULL, 1),
(539224, 54575, 3102, '<td valign="top">This would have been cool with a little sharper focus.</td>', 'This would have been cool with a little sharper focus.', '2004-01-12 00:26:06.000000', NULL, 1),
(539225, 54764, 3080, '<td valign="top">Love the sky.  Really beautiful.  The birds and the pole seem to be a bit soft on the focus though.  that would be my only suggestion would be that I wish they were a bit more crisp.  Otherwise, a really pretty shot.  I like how you put the pole to one side, and not directly in the middle of the shot.  Definately makes a difference on how this looks.  nice find. ~Heather~</td>', 'Love the sky.  Really beautiful.  The birds and the pole seem to be a bit soft on the focus though.  that would be my only suggestion would be that I wish they were a bit more crisp.  Otherwise, a really pretty shot.  I like how you put the pole to one side, and not directly in the middle of the shot.  Definately makes a difference on how this looks.  nice find. ~Heather~', '2004-01-12 00:28:05.000000', NULL, 1),
(539234, 53919, 3080, '<td valign="top">I love flowers on black backgrounds.  Some people hate it, but not me.  You have some excellent color, and wonderful texture here.  The only spot I''m finding a bit distracting is the petal that is fight above the green leaf inthe bottom left corner.  It seems to be blurry, where the rest of the shot is nice and crisp focus.  Not sure if that was your DOF, but I think it would have enhanced the shot just a bit to have that petal in focus as well.  Otherwise, very nice lighting, and great close up.  Beautiful flower.  ~Heather~</td>', 'I love flowers on black backgrounds.  Some people hate it, but not me.  You have some excellent color, and wonderful texture here.  The only spot I''m finding a bit distracting is the petal that is fight above the green leaf inthe bottom left corner.  It seems to be blurry, where the rest of the shot is nice and crisp focus.  Not sure if that was your DOF, but I think it would have enhanced the shot just a bit to have that petal in focus as well.  Otherwise, very nice lighting, and great close up.  Beautiful flower.  ~Heather~', '2004-01-12 00:47:58.000000', NULL, 1),
(539243, 54527, 6668, '<td valign="top">Beautiful shot....although I think it could do without the border. 9</td>', 'Beautiful shot....although I think it could do without the border. 9', '2004-01-12 00:55:50.000000', NULL, 1),
(539244, 54514, 3080, '<td valign="top">Are those shoes?  I''m a little confused as to what I''m looking at here.  I can''t say that the subject matter is appealing to me.  The very bright light almost dead center of your shot is a distraction to the subject, which I can''t really figure out what IS the subject.  The challenge was to take a pic of your subject that is more interesting after dark.  Is that the people?  Is that the shoes?  the umbrellas?</td>', 'Are those shoes?  I''m a little confused as to what I''m looking at here.  I can''t say that the subject matter is appealing to me.  The very bright light almost dead center of your shot is a distraction to the subject, which I can''t really figure out what IS the subject.  The challenge was to take a pic of your subject that is more interesting after dark.  Is that the people?  Is that the shoes?  the umbrellas?', '2004-01-12 00:56:22.000000', NULL, 1),
(539246, 53986, 12160, '<td valign="top">Nice composition. Love the color tone, it feels very cold and calm.</td>', 'Nice composition. Love the color tone, it feels very cold and calm.', '2004-01-12 00:59:37.000000', NULL, 1),
(539251, 54542, 6668, '<td valign="top">awesome shot! 10</td>', 'awesome shot! 10', '2004-01-12 01:04:05.000000', NULL, 1),
(539252, 54690, 6668, '<td valign="top">would be better if it was larger and showed more detail.</td>', 'would be better if it was larger and showed more detail.', '2004-01-12 01:05:57.000000', NULL, 1),
(539257, 54594, 6668, '<td valign="top">Wow...what a powerful shot..very moving, as a mother myself..it gives me chills.<br/> <br/>The only problem I have with the photo itself, is the cross behind the girl that is right in the middle of her back, although I know it couldn''t be helped it is a bit distracting. 8</td>', 'Wow...what a powerful shot..very moving, as a mother myself..it gives me chills. The only problem I have with the photo itself, is the cross behind the girl that is right in the middle of her back, although I know it couldn''t be helped it is a bit distracting. 8', '2004-01-12 01:16:42.000000', NULL, 1),
(539263, 54614, 13403, '<td valign="top">badass- you''d have my vote if i actually paid for my membership..</td>', 'badass- you''d have my vote if i actually paid for my membership..', '2004-01-12 01:30:44.000000', NULL, 1),
