(539288, 54261, 5158, '<td valign="top">Hey, that''s a Toyota, isn''t it? Looks like my Camry.<br/>Like the reflections from the rain. It''s well exposed. The tilt is a little strong for my taste.</td>', 'Hey, that''s a Toyota, isn''t it? Looks like my Camry.Like the reflections from the rain. It''s well exposed. The tilt is a little strong for my taste.', '2004-01-12 02:28:26.000000', NULL, 1),
(539290, 54668, 12160, '<td valign="top">Excellent backlighting, great exposure and composition. I like color of the lit cig that is very distinct from the rest of the photo. 8</td>', 'Excellent backlighting, great exposure and composition. I like color of the lit cig that is very distinct from the rest of the photo. 8', '2004-01-12 02:30:19.000000', NULL, 1),
(539291, 54338, 15407, '<td valign="top">I''d have been blind for awhile after that shot...</td>', 'I''d have been blind for awhile after that shot...', '2004-01-12 02:32:27.000000', NULL, 1),
(539292, 54624, 12160, '<td valign="top">beautiful sunset colors, the clouds are nice too.</td>', 'beautiful sunset colors, the clouds are nice too.', '2004-01-12 02:32:56.000000', NULL, 1),
(539293, 54201, 12160, '<td valign="top">Very sharp image, well-exposed.</td>', 'Very sharp image, well-exposed.', '2004-01-12 02:35:11.000000', NULL, 1),
