(539304, 54598, 12802, '<td valign="top">one night sailed off in a wooden shoe.....  That brings back memories!<br/> <br/>Good night shot, a little overexposed at the main light in the middle, draws my eyes to it.  8</td>', 'one night sailed off in a wooden shoe.....  That brings back memories! Good night shot, a little overexposed at the main light in the middle, draws my eyes to it.  8', '2004-01-12 03:01:25.000000', NULL, 1),
(539321, 54530, 15407, '<td valign="top">It''s a shame the light pole could not have been hidden behind the statue.  It is still a nice shot though.</td>', 'It''s a shame the light pole could not have been hidden behind the statue.  It is still a nice shot though.', '2004-01-12 03:56:00.000000', NULL, 1),
(539327, 54599, 4517, '<td valign="top">Amazing pic, even with the hot pixel.10</td>', 'Amazing pic, even with the hot pixel.10', '2004-01-12 04:10:58.000000', NULL, 1),
(539333, 54671, 8643, '<td valign="top">Great idea, simple but very effective</td>', 'Great idea, simple but very effective', '2004-01-12 04:38:40.000000', NULL, 1),
(539336, 54599, 10084, '<td valign="top">The lighting makes it seem like another world. The beautiful blue hues in the sky really help to make the mountain pop out of the shot.</td>', 'The lighting makes it seem like another world. The beautiful blue hues in the sky really help to make the mountain pop out of the shot.', '2004-01-12 04:41:32.000000', NULL, 1),
(539341, 54514, 8139, '<td valign="top">Overall interest : 2/3<br/>Technical : 1/3 (The spot lamps are too bright and distract from the main subject, the blurred person at right could be cropped out, and contrast improved a bit )<br/>Challenge meeting : 1/2 (the same market scene at day should be interesting too)<br/>WOW factor : 0/2 (sorry)</td>', 'Overall interest : 2/3Technical : 1/3 (The spot lamps are too bright and distract from the main subject, the blurred person at right could be cropped out, and contrast improved a bit )Challenge meeting : 1/2 (the same market scene at day should be interesting too)WOW factor : 0/2 (sorry)', '2004-01-12 04:51:47.000000', NULL, 1),
(539343, 54523, 8139, '<td valign="top">Overall interest : 1/3<br/>Technical : 2/3 (apply the rules of third to the spot light had improved IMHO)<br/>Challenge meeting : 1/2 (The night shot add a night mood, but no more)<br/>WOW factor : 1/2 (lighting effects)</td>', 'Overall interest : 1/3Technical : 2/3 (apply the rules of third to the spot light had improved IMHO)Challenge meeting : 1/2 (The night shot add a night mood, but no more)WOW factor : 1/2 (lighting effects)', '2004-01-12 05:13:21.000000', NULL, 1),
