(539516, 54223, 6359, '<td valign="top">A little over-exposed for my taste.</td>', 'A little over-exposed for my taste.', '2004-01-12 10:02:27.000000', NULL, 1),
(539517, 54766, 9932, '<td valign="top">Very nice I feel the WB ballance may be off just a tad. Nice work.</td>', 'Very nice I feel the WB ballance may be off just a tad. Nice work.', '2004-01-12 10:03:46.000000', NULL, 1),
(539518, 54458, 6359, '<td valign="top">I like the shot but there is a haze on the photo.</td>', 'I like the shot but there is a haze on the photo.', '2004-01-12 10:03:58.000000', NULL, 1),
