(539521, 54488, 6359, '<td valign="top">interesting.</td>', 'interesting.', '2004-01-12 10:04:28.000000', NULL, 1),
(539522, 54313, 13136, '<td valign="top">I''m not sure what to make of the green tint to everything. Good composition and lighting.</td>', 'I''m not sure what to make of the green tint to everything. Good composition and lighting.', '2004-01-12 10:05:07.000000', NULL, 1),
(539523, 54627, 6359, '<td valign="top">I like but wished there was just a little more details in shadows.</td>', 'I like but wished there was just a little more details in shadows.', '2004-01-12 10:05:27.000000', NULL, 1),
(539524, 53919, 13136, '<td valign="top">There is nothing different in this from many other flower shots to make me believe it is "After Dark". The light on it is too harse while the green stem on the left is distracting.</td>', 'There is nothing different in this from many other flower shots to make me believe it is "After Dark". The light on it is too harse while the green stem on the left is distracting.', '2004-01-12 10:06:43.000000', NULL, 1),
