(539550, 54672, 6870, '<td valign="top">Fascinating shapes and rhythms here. LIghting is interesting, too. Title matches the weirdness of the subjects! YOu might want to experiment with tigher cropping to bring even more focus on the strange balls.</td>', 'Fascinating shapes and rhythms here. LIghting is interesting, too. Title matches the weirdness of the subjects! YOu might want to experiment with tigher cropping to bring even more focus on the strange balls.', '2004-01-12 10:18:27.000000', NULL, 1),
(539551, 54671, 6359, '<td valign="top">Better photo after dark?</td>', 'Better photo after dark?', '2004-01-12 10:19:02.000000', NULL, 1),
(539552, 54033, 13136, '<td valign="top">Looks a little foggy or grainy. Nice shot though, with good reflection/lighting on the water. I might have included just a little more sky.</td>', 'Looks a little foggy or grainy. Nice shot though, with good reflection/lighting on the water. I might have included just a little more sky.', '2004-01-12 10:19:05.000000', NULL, 1),
(539555, 54690, 6870, '<td valign="top">Don''t crash! A very formal, direct view of this console that gives us a look into the complexity of it all. You might want to experiment with different points of view to increase the drama and interest, too.</td>', 'Don''t crash! A very formal, direct view of this console that gives us a look into the complexity of it all. You might want to experiment with different points of view to increase the drama and interest, too.', '2004-01-12 10:19:53.000000', NULL, 1),
(539557, 54668, 13136, '<td valign="top">Nice backlighting and glow on the cigarette. Good response to the challenge.</td>', 'Nice backlighting and glow on the cigarette. Good response to the challenge.', '2004-01-12 10:20:24.000000', NULL, 1),
(539558, 54730, 6359, '<td valign="top">Wouldn''t sepia layer/mode be better.</td>', 'Wouldn''t sepia layer/mode be better.', '2004-01-12 10:20:29.000000', NULL, 1),
