(540966, 54711, 6870, '<td valign="top">I really like the drama of the smoke here. The vegetation on the right adds an interesting element.</td>', 'I really like the drama of the smoke here. The vegetation on the right adds an interesting element.', '2004-01-13 10:52:37.000000', NULL, 1),
(540967, 54380, 6870, '<td valign="top">Nice bike! I rode an Indian once. It was fun! I can''t afford one, though. Your lighting is very interesting and unique here, but I really enjoy how the diffused light from below lights up the machine, causing interesting highlights and shadows.</td>', 'Nice bike! I rode an Indian once. It was fun! I can''t afford one, though. Your lighting is very interesting and unique here, but I really enjoy how the diffused light from below lights up the machine, causing interesting highlights and shadows.', '2004-01-13 10:54:05.000000', NULL, 1),
(540968, 54613, 5728, '<td valign="top">Nice colors here, I like the composition and the effect of the longer shutter speed. One blown out spot with a red halo around in on the middle building at the top is rather distracting.</td>', 'Nice colors here, I like the composition and the effect of the longer shutter speed. One blown out spot with a red halo around in on the middle building at the top is rather distracting.', '2004-01-13 10:54:59.000000', NULL, 1),
(540970, 54488, 6870, '<td valign="top">I see you''ve been sneaking around my  house, taking pictures of me! How dastardly of you! I really like this shot. Your strong composition and point of view makes that gargoyle really stick out. Lighting is just a bit harsh, but a fun image.</td>', 'I see you''ve been sneaking around my  house, taking pictures of me! How dastardly of you! I really like this shot. Your strong composition and point of view makes that gargoyle really stick out. Lighting is just a bit harsh, but a fun image.', '2004-01-13 10:55:18.000000', NULL, 1),
(540971, 54774, 5728, '<td valign="top">Good night shot, the exposure is spot on, no hotspots at all!</td>', 'Good night shot, the exposure is spot on, no hotspots at all!', '2004-01-13 10:55:50.000000', NULL, 1),
(540972, 54773, 6870, '<td valign="top">Lovely sky and sillhouette. Very well balanced both horiz and vertically. The reflections in the water add some nice detail.</td>', 'Lovely sky and sillhouette. Very well balanced both horiz and vertically. The reflections in the water add some nice detail.', '2004-01-13 10:56:05.000000', NULL, 1),
(540974, 54527, 5728, '<td valign="top">Lucky you being in Paris this week! I would have done exactly the same shot had I been there. The Eiffel Tower is soooo photogenic! You did this one well.</td>', 'Lucky you being in Paris this week! I would have done exactly the same shot had I been there. The Eiffel Tower is soooo photogenic! You did this one well.', '2004-01-13 10:56:52.000000', NULL, 1),
(540975, 54614, 6870, '<td valign="top">This looks like something from a  horror movie all right. I prefer the wide blurry strokes to the th inner, more ''legible'' strokes at left. Really fun idea.</td>', 'This looks like something from a  horror movie all right. I prefer the wide blurry strokes to the th inner, more ''legible'' strokes at left. Really fun idea.', '2004-01-13 10:57:17.000000', NULL, 1),
(540976, 54725, 5728, '<td valign="top">Good shot. The light is a little too harsh from the left hand side, showing on the top of the phone and the lower part of the book.</td>', 'Good shot. The light is a little too harsh from the left hand side, showing on the top of the phone and the lower part of the book.', '2004-01-13 10:57:46.000000', NULL, 1),
(540978, 54324, 6870, '<td valign="top">Earl Abel''s looks closed, ironically. THe figure at left adds a lot of interest to the shot. IMage is well balanced and engaging.</td>', 'Earl Abel''s looks closed, ironically. THe figure at left adds a lot of interest to the shot. IMage is well balanced and engaging.', '2004-01-13 10:58:26.000000', NULL, 1),
(540982, 54736, 772, '<td valign="top">This shot meets the challenge, but I don''t find the image particularly interesting overall.  It seems to lack a strong subject element.</td>', 'This shot meets the challenge, but I don''t find the image particularly interesting overall.  It seems to lack a strong subject element.', '2004-01-13 11:02:49.000000', NULL, 1),
(540989, 54276, 12061, '<td valign="top">the lighting in this shot is fantastic! I love it!</td>', 'the lighting in this shot is fantastic! I love it!', '2004-01-13 11:08:58.000000', NULL, 1),
(540993, 54599, 4338, '<td valign="top">great shot, i love the colors</td>', 'great shot, i love the colors', '2004-01-13 11:10:26.000000', NULL, 1),
(540995, 54593, 12061, '<td valign="top">this is such a simple shot, yet I love how it looks. The dimmed lights are great<br/>i also love the person walking by in the shot - gives it a mysterious feeling. Excellent job.</td>', 'this is such a simple shot, yet I love how it looks. The dimmed lights are greati also love the person walking by in the shot - gives it a mysterious feeling. Excellent job.', '2004-01-13 11:10:53.000000', NULL, 1),
(541001, 54374, 4338, '<td valign="top">image looks out of focus, or maybe you focused on the moon and the exposure was a bit too long and over exposed the moon so you cant tell what should be infocus</td>', 'image looks out of focus, or maybe you focused on the moon and the exposure was a bit too long and over exposed the moon so you cant tell what should be infocus', '2004-01-13 11:13:25.000000', NULL, 1),
(541006, 54749, 4338, '<td valign="top">great shot, I have been there in the summer, but never the winter. I would love to see some of you other shots once the challenge is over</td>', 'great shot, I have been there in the summer, but never the winter. I would love to see some of you other shots once the challenge is over', '2004-01-13 11:17:10.000000', NULL, 1),
(541011, 54642, 4338, '<td valign="top">lovely photo, great job</td>', 'lovely photo, great job', '2004-01-13 11:19:29.000000', NULL, 1),
(541038, 54642, 5728, '<td valign="top">I love the greeness which you''ve brought out there, it mixes in well with the purple colored night sky. The exposure and lighting is spot on here</td>', 'I love the greeness which you''ve brought out there, it mixes in well with the purple colored night sky. The exposure and lighting is spot on here', '2004-01-13 11:46:43.000000', NULL, 1),
(541039, 54565, 5728, '<td valign="top">This is not a very photogenic area to take a photogrphaph, in fact it is pretty ugly. But through the effect of the train and the red and white color motion mix you have changed all that and created something really worth looking at.</td>', 'This is not a very photogenic area to take a photogrphaph, in fact it is pretty ugly. But through the effect of the train and the red and white color motion mix you have changed all that and created something really worth looking at.', '2004-01-13 11:48:38.000000', NULL, 1),
(541056, 54665, 12654, '<td valign="top">Nice shot love the silhouette  against the sunset- nice shot - have to look closely to see the person in the pic.</td>', 'Nice shot love the silhouette  against the sunset- nice shot - have to look closely to see the person in the pic.', '2004-01-13 11:56:05.000000', NULL, 1),
(541057, 54662, 12654, '<td valign="top">This is such a cool picture - looks so futuristic - like something out of a star wars movie!</td>', 'This is such a cool picture - looks so futuristic - like something out of a star wars movie!', '2004-01-13 11:57:42.000000', NULL, 1),
(541070, 54662, 11073, '<td valign="top">nice pov.  the look created is pleasing to the eye.  this would probably be strong as a b/w too.  Nice work.</td>', 'nice pov.  the look created is pleasing to the eye.  this would probably be strong as a b/w too.  Nice work.', '2004-01-13 12:24:25.000000', NULL, 1),
(541077, 54672, 14620, '<td valign="top">What a great subject!  This is a wonderful picture, one of my favorites.  I love the lighting and the flow of the water.  I wish there was less of the building behind it, but all in all, this is fantastic!</td>', 'What a great subject!  This is a wonderful picture, one of my favorites.  I love the lighting and the flow of the water.  I wish there was less of the building behind it, but all in all, this is fantastic!', '2004-01-13 12:35:13.000000', NULL, 1),
(541080, 54514, 11073, '<td valign="top">good pov for this shot.  the composition of the people and the umbrellas is really strong.  it looks like you''re down low to get this shot.  that really pulls the viewer into the frame but at the same time keeping a strictly vouyeur look.  nice work.</td>', 'good pov for this shot.  the composition of the people and the umbrellas is really strong.  it looks like you''re down low to get this shot.  that really pulls the viewer into the frame but at the same time keeping a strictly vouyeur look.  nice work.', '2004-01-13 12:36:07.000000', NULL, 1),
(541081, 54662, 14620, '<td valign="top">Menacing indeed!  Fantastic clarity, especially for a night shot.  Great lighting and composition.  Did you use a long shutter speed to capture the movement of the clouds?  The blur of the clouds against the sharpness of the building really makes this shot for me.  And even though there isn''t alot of it, I like the coloring of the picture!  Great Photo!</td>', 'Menacing indeed!  Fantastic clarity, especially for a night shot.  Great lighting and composition.  Did you use a long shutter speed to capture the movement of the clouds?  The blur of the clouds against the sharpness of the building really makes this shot for me.  And even though there isn''t alot of it, I like the coloring of the picture!  Great Photo!', '2004-01-13 12:38:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(541082, 54668, 11073, '<td valign="top">very cool.</td>', 'very cool.', '2004-01-13 12:39:58.000000', NULL, 1),
(541083, 54688, 14620, '<td valign="top">Beautiful!  I love the subtle mood this picture creates.  The colors are very warm which adds a nice contrast to what looks to be snow on the ground.  Nice lighting from behind.</td>', 'Beautiful!  I love the subtle mood this picture creates.  The colors are very warm which adds a nice contrast to what looks to be snow on the ground.  Nice lighting from behind.', '2004-01-13 12:41:09.000000', NULL, 1),
(541085, 54542, 14620, '<td valign="top">Beautiful night sky and  a great capture of traffic.  Great night shot!</td>', 'Beautiful night sky and  a great capture of traffic.  Great night shot!', '2004-01-13 12:43:01.000000', NULL, 1),
(541090, 54772, 14620, '<td valign="top">Very nice composition.  The orange neon really makes this pop!</td>', 'Very nice composition.  The orange neon really makes this pop!', '2004-01-13 12:47:26.000000', NULL, 1),
