(541194, 54672, 11155, '<td valign="top">Wow, what interesting subjects!  Cool lighting too.  Good luck.</td>', 'Wow, what interesting subjects!  Cool lighting too.  Good luck.', '2004-01-13 15:04:29.000000', NULL, 1),
(541195, 54178, 11155, '<td valign="top">I like the orange/blue contrast.  Creative angle too.</td>', 'I like the orange/blue contrast.  Creative angle too.', '2004-01-13 15:04:52.000000', NULL, 1),
(541197, 54542, 11155, '<td valign="top">Wonderful colors in this.  One of the better traffic at night shots I''ve seen.  Nice work - sky is nice.</td>', 'Wonderful colors in this.  One of the better traffic at night shots I''ve seen.  Nice work - sky is nice.', '2004-01-13 15:06:47.000000', NULL, 1),
(541198, 54662, 11155, '<td valign="top">This is a very cool, ominous image!  Might like it even better if the bottom yellowish glass structure wasn''t visible.  Sky is great.  Nice work.</td>', 'This is a very cool, ominous image!  Might like it even better if the bottom yellowish glass structure wasn''t visible.  Sky is great.  Nice work.', '2004-01-13 15:07:48.000000', NULL, 1),
(541205, 54711, 5728, '<td valign="top">Finely captured! Did you plan this one out like this? Amazing colors. I myself would have cropped out more from the bottom and left more sky in the top.</td>', 'Finely captured! Did you plan this one out like this? Amazing colors. I myself would have cropped out more from the bottom and left more sky in the top.', '2004-01-13 15:19:27.000000', NULL, 1),
(541207, 54343, 11155, '<td valign="top">Interesting subject and exposure is perfect.</td>', 'Interesting subject and exposure is perfect.', '2004-01-13 15:20:47.000000', NULL, 1),
(541209, 54668, 11155, '<td valign="top">Lighting is great on this and so is the pose.  The title seems a little cheesy, but that wouldn''t cause me to deduct any points for this.  Nice work.</td>', 'Lighting is great on this and so is the pose.  The title seems a little cheesy, but that wouldn''t cause me to deduct any points for this.  Nice work.', '2004-01-13 15:21:40.000000', NULL, 1),
(541213, 54744, 11155, '<td valign="top">Wonderful winter scene.  Lighting is nice.</td>', 'Wonderful winter scene.  Lighting is nice.', '2004-01-13 15:24:54.000000', NULL, 1),
(541308, 54744, 6900, '<td valign="top">Stellar shot.  The first I viewed and a real pleaser.  9</td>', 'Stellar shot.  The first I viewed and a real pleaser.  9', '2004-01-13 17:28:36.000000', NULL, 1),
(541310, 54771, 6900, '<td valign="top">Not much after dark here.  Why is this more interesting at night?</td>', 'Not much after dark here.  Why is this more interesting at night?', '2004-01-13 17:28:51.000000', NULL, 1),
