(543613, 54530, 5822, '<td valign="top">Lighting is a bit harsh and there appears to be some chromatic abberation down at the bottom. Other than that, I like your angle of view.</td>', 'Lighting is a bit harsh and there appears to be some chromatic abberation down at the bottom. Other than that, I like your angle of view.', '2004-01-14 20:17:07.000000', NULL, 1),
(543617, 54477, 5822, '<td valign="top">YOu''ve taken so much in in this wide angled shot that it looks like a jumbled mess with little detail. Not crazy about the colors either.</td>', 'YOu''ve taken so much in in this wide angled shot that it looks like a jumbled mess with little detail. Not crazy about the colors either.', '2004-01-14 20:20:00.000000', NULL, 1),
(543623, 54773, 5822, '<td valign="top">Very nice subtle coloring and lighting.  Just think that the branch in the upper left should not be there.</td>', 'Very nice subtle coloring and lighting.  Just think that the branch in the upper left should not be there.', '2004-01-14 20:24:51.000000', NULL, 1),
(543772, 54598, 10818, '<td valign="top">Great photo.  Wonderful lights, and the smoke (or steam) out of the stacks is awesome.  Great job.</td>', 'Great photo.  Wonderful lights, and the smoke (or steam) out of the stacks is awesome.  Great job.', '2004-01-14 21:51:51.000000', NULL, 1),
(543775, 54033, 10848, '<td valign="top">Beautiful shot, the B&amp;W choice adds to this shot in my opinion, your exposure was perfect the lights on the shore line are great</td>', 'Beautiful shot, the B&W choice adds to this shot in my opinion, your exposure was perfect the lights on the shore line are great', '2004-01-14 21:53:08.000000', NULL, 1),
(543777, 54599, 10818, '<td valign="top">That is an amazing photo.  I love the red star (mars?).  Perfect 10.</td>', 'That is an amazing photo.  I love the red star (mars?).  Perfect 10.', '2004-01-14 21:54:00.000000', NULL, 1),
(543778, 54553, 10848, '<td valign="top">Beautiful shot , this looks like a wonderful Christmas card. Great detail and the warm lighting makes this all the more elegant and beautiful 8</td>', 'Beautiful shot , this looks like a wonderful Christmas card. Great detail and the warm lighting makes this all the more elegant and beautiful 8', '2004-01-14 21:54:25.000000', NULL, 1),
(543780, 54716, 10848, '<td valign="top">I love these long exposure shots they always amaze me, this is a wonderful capture of the headlights and tailights, pefect challenge match good job</td>', 'I love these long exposure shots they always amaze me, this is a wonderful capture of the headlights and tailights, pefect challenge match good job', '2004-01-14 21:55:57.000000', NULL, 1),
(543784, 54380, 10848, '<td valign="top">Wow good shot, I can say that if this is a model and not the real thing you certainly did an excellent job. Great lighting and detail. 10</td>', 'Wow good shot, I can say that if this is a model and not the real thing you certainly did an excellent job. Great lighting and detail. 10', '2004-01-14 21:58:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(543785, 54608, 10818, '<td valign="top">Very nice, clear photo.  Good luck.</td>', 'Very nice, clear photo.  Good luck.', '2004-01-14 21:59:06.000000', NULL, 1),
(543788, 54477, 10818, '<td valign="top">I wish I could see it larger.  But I do like it.  Nice job.</td>', 'I wish I could see it larger.  But I do like it.  Nice job.', '2004-01-14 22:00:06.000000', NULL, 1),
(543789, 54594, 10848, '<td valign="top">This shot really touched me, I must say you certainly accomplished what all photographers go for, and that is to touch your viewer with your shot, great job</td>', 'This shot really touched me, I must say you certainly accomplished what all photographers go for, and that is to touch your viewer with your shot, great job', '2004-01-14 22:00:25.000000', NULL, 1),
(543798, 54642, 10848, '<td valign="top">Beautiful shot, great detail and contrast</td>', 'Beautiful shot, great detail and contrast', '2004-01-14 22:03:00.000000', NULL, 1),
(543799, 54613, 10818, '<td valign="top">Its really a great shot.  Seems a bit too much with the red though.  Very nice steam coming from the buildings.</td>', 'Its really a great shot.  Seems a bit too much with the red though.  Very nice steam coming from the buildings.', '2004-01-14 22:03:15.000000', NULL, 1),
(543800, 54774, 10848, '<td valign="top">This is great, it looks like a futurisic blast from the past roadside diner, you captured this shot perfectly</td>', 'This is great, it looks like a futurisic blast from the past roadside diner, you captured this shot perfectly', '2004-01-14 22:04:24.000000', NULL, 1),
(543808, 54624, 10818, '<td valign="top">What a great shot.  Nice reflection in the background, and wonderful colors.   Very easy to overdo the saturation or the sharpening with a shot like this.  You did niether.  Great job.</td>', 'What a great shot.  Nice reflection in the background, and wonderful colors.   Very easy to overdo the saturation or the sharpening with a shot like this.  You did niether.  Great job.', '2004-01-14 22:11:02.000000', NULL, 1),
(543818, 54703, 10848, '<td valign="top">Beautiful shot, who cannot relate to this shot? Great detail perfect exposure, great job 9</td>', 'Beautiful shot, who cannot relate to this shot? Great detail perfect exposure, great job 9', '2004-01-14 22:15:54.000000', NULL, 1),
(543823, 54662, 10818, '<td valign="top">Very nice.  Wonder if it would be better with the bottom cropped.?  I dont know really, just a thought......great photo though.  8</td>', 'Very nice.  Wonder if it would be better with the bottom cropped.?  I dont know really, just a thought......great photo though.  8', '2004-01-14 22:17:33.000000', NULL, 1),
(543833, 54712, 10848, '<td valign="top">This is a very beautiful and serene shot, the exposure is just a little off but not enough to affect the quality of this shot 8</td>', 'This is a very beautiful and serene shot, the exposure is just a little off but not enough to affect the quality of this shot 8', '2004-01-14 22:20:33.000000', NULL, 1),
(543839, 54743, 10818, '<td valign="top">I think its a great shot.  Too bad its overpixiated&lt;---------is that a word?<br/>I wish you the best.</td>', 'I think its a great shot.  Too bad its overpixiated<---------is that a word?I wish you the best.', '2004-01-14 22:21:59.000000', NULL, 1),
(543846, 54530, 10848, '<td valign="top">Great shot, the lighting is outstanding, the angle is great also</td>', 'Great shot, the lighting is outstanding, the angle is great also', '2004-01-14 22:25:38.000000', NULL, 1),
(543853, 54773, 10848, '<td valign="top">This shot caught my eye right away, the detail in this is outstanding, the colors and the contrast are superb, the distant silhoutte of the city really adds to this shot 10</td>', 'This shot caught my eye right away, the detail in this is outstanding, the colors and the contrast are superb, the distant silhoutte of the city really adds to this shot 10', '2004-01-14 22:29:10.000000', NULL, 1),
