(544150, 54767, 9906, '<td valign="top">IMHO this would be even better without the car lights moving.  Or with much more moving car lights...<br/>TC</td>', 'IMHO this would be even better without the car lights moving.  Or with much more moving car lights...TC', '2004-01-15 01:26:10.000000', NULL, 1),
(544158, 54744, 9906, '<td valign="top">With low lite shots like this its sometimes difficult to tell if a shot has been duotone treated or is natural.  This is one of them.  Either way, love the tonality!<br/>TC</td>', 'With low lite shots like this its sometimes difficult to tell if a shot has been duotone treated or is natural.  This is one of them.  Either way, love the tonality!TC', '2004-01-15 01:29:49.000000', NULL, 1),
(544163, 54671, 9906, '<td valign="top">LOL  I think that this is a part of growing up!  Been there done that!  Only thing missing is the covers over the head!  Bonus points for originality AND cute model.<br/>TC</td>', 'LOL  I think that this is a part of growing up!  Been there done that!  Only thing missing is the covers over the head!  Bonus points for originality AND cute model.TC', '2004-01-15 01:32:56.000000', NULL, 1),
