(544205, 54488, 9906, '<td valign="top">Very cool!  What building is this?  Don''t have anything this old around here. :-(<br/>TC</td>', 'Very cool!  What building is this?  Don''t have anything this old around here. :-(TC', '2004-01-15 02:03:20.000000', NULL, 1),
(544207, 54725, 9906, '<td valign="top">Get rid of the extraneous foreground elements and this would be more poigniant.  Also glare on arm and book page are distracting and take attention away from the subject...<br/>TC</td>', 'Get rid of the extraneous foreground elements and this would be more poigniant.  Also glare on arm and book page are distracting and take attention away from the subject...TC', '2004-01-15 02:05:34.000000', NULL, 1),
