(545301, 54542, 11078, '<td valign="top">great effects I can only stand in awe and admire your work</td>', 'great effects I can only stand in awe and admire your work', '2004-01-15 21:23:30.000000', NULL, 1),
(545305, 54261, 11078, '<td valign="top">great and unusual idea nicely focused</td>', 'great and unusual idea nicely focused', '2004-01-15 21:24:45.000000', NULL, 1),
(545308, 54770, 11078, '<td valign="top">simple but good</td>', 'simple but good', '2004-01-15 21:26:23.000000', NULL, 1),
(545315, 54627, 11078, '<td valign="top">i like this its a bit creepy and yet still inviting</td>', 'i like this its a bit creepy and yet still inviting', '2004-01-15 21:29:45.000000', NULL, 1),
(545324, 54671, 11078, '<td valign="top">I like this very sharp and nice idea good camera work</td>', 'I like this very sharp and nice idea good camera work', '2004-01-15 21:32:21.000000', NULL, 1),
(545390, 54767, 16203, '<td valign="top">I love this photo because I lived outside KC during my college years. This place is so wonderful during Christmas time. Nice capture of the spot lights in the background.</td>', 'I love this photo because I lived outside KC during my college years. This place is so wonderful during Christmas time. Nice capture of the spot lights in the background.', '2004-01-15 22:12:00.000000', NULL, 1),
(545404, 54599, 2333, '<td valign="top">Absolutely... outstanding. Exceptional colors, composition is great, creates a wonderful atmosphere.</td>', 'Absolutely... outstanding. Exceptional colors, composition is great, creates a wonderful atmosphere.', '2004-01-15 22:31:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(545406, 54717, 2333, '<td valign="top">Exceptionally well executed, high interest. Perfectly exposed. the blurred smoke is a perfect counterpoint to the perfect crispness of the... um, I''m guessing... refinery?</td>', 'Exceptionally well executed, high interest. Perfectly exposed. the blurred smoke is a perfect counterpoint to the perfect crispness of the... um, I''m guessing... refinery?', '2004-01-15 22:32:37.000000', NULL, 1),
(545407, 54688, 2333, '<td valign="top">Beautiful. Simple, elegant, great mood. Good choice of color, exposure.</td>', 'Beautiful. Simple, elegant, great mood. Good choice of color, exposure.', '2004-01-15 22:33:25.000000', NULL, 1),
(545409, 54662, 2333, '<td valign="top">Ahh, the fas-moving clouds were definitely your friend. Great effect. Like the composition.</td>', 'Ahh, the fas-moving clouds were definitely your friend. Great effect. Like the composition.', '2004-01-15 22:34:25.000000', NULL, 1),
(545411, 54324, 2333, '<td valign="top">excellent choice of exposure. Very nice composition. I wouldn''t change your crop, but I do find the person standing at left distracting. I think the shot woudl be better without him.</td>', 'excellent choice of exposure. Very nice composition. I wouldn''t change your crop, but I do find the person standing at left distracting. I think the shot woudl be better without him.', '2004-01-15 22:37:45.000000', NULL, 1),
(545422, 54201, 8624, '<td valign="top">you''ve combined 2 subjects that I like a lot - a night shot and industrial scenes. Exposure is right on with nice clear crisp details and zero noise and there are lots of interesting visual elements. The framing of the subject, though, looks a little off to me. I generally like good use of negative space, but the composition seems unbalanced to me.</td>', 'you''ve combined 2 subjects that I like a lot - a night shot and industrial scenes. Exposure is right on with nice clear crisp details and zero noise and there are lots of interesting visual elements. The framing of the subject, though, looks a little off to me. I generally like good use of negative space, but the composition seems unbalanced to me.', '2004-01-15 23:00:33.000000', NULL, 1),
(545424, 54662, 8624, '<td valign="top">excellent capture. I assume this is a long exposure looking at the sky. colors are terrific and the shot is tack sharp with no noise. I really like the angle. I haven''t decided if I would like this better or not if the reflection of the other building was absent, but either way this is a terrific image. 9</td>', 'excellent capture. I assume this is a long exposure looking at the sky. colors are terrific and the shot is tack sharp with no noise. I really like the angle. I haven''t decided if I would like this better or not if the reflection of the other building was absent, but either way this is a terrific image. 9', '2004-01-15 23:03:13.000000', NULL, 1),
(545425, 54624, 8624, '<td valign="top">nice sky colors.</td>', 'nice sky colors.', '2004-01-15 23:04:11.000000', NULL, 1),
(545427, 54534, 8624, '<td valign="top">creative presentation. good catchlights in the soldier''s eyes.</td>', 'creative presentation. good catchlights in the soldier''s eyes.', '2004-01-15 23:05:26.000000', NULL, 1),
(545429, 54613, 8624, '<td valign="top">great scne. I like the smoke/steam blowing off the tops of the twin buildings on the left and the partial view of the elliptical roof in the lower right. Has a neat "Blade Runner" feel to it. 8</td>', 'great scne. I like the smoke/steam blowing off the tops of the twin buildings on the left and the partial view of the elliptical roof in the lower right. Has a neat "Blade Runner" feel to it. 8', '2004-01-15 23:07:16.000000', NULL, 1),
(545430, 54575, 8624, '<td valign="top">shot is pretty soft but your lighting is good. was this handheld? maybe use a tripod or other support next time.</td>', 'shot is pretty soft but your lighting is good. was this handheld? maybe use a tripod or other support next time.', '2004-01-15 23:08:02.000000', NULL, 1),
(545431, 54725, 8624, '<td valign="top">nice lighting and a decent portrait but the phone really hurts the composition. If the phone wasn''t there it would be a stronger shot.</td>', 'nice lighting and a decent portrait but the phone really hurts the composition. If the phone wasn''t there it would be a stronger shot.', '2004-01-15 23:09:52.000000', NULL, 1),
(545458, 54719, 11078, '<td valign="top">What a scary sight<br/>Nice work</td>', 'What a scary sightNice work', '2004-01-16 00:28:36.000000', NULL, 1),
(545460, 54712, 11078, '<td valign="top">I like this  as it unfolded onto my screen I found a beautiful sight <br/>I would love a place like that<br/>Great work</td>', 'I like this  as it unfolded onto my screen I found a beautiful sight I would love a place like thatGreat work', '2004-01-16 00:31:40.000000', NULL, 1),
(545462, 54721, 11078, '<td valign="top">very nice clear and well focused</td>', 'very nice clear and well focused', '2004-01-16 00:32:44.000000', NULL, 1),
(545463, 54374, 11078, '<td valign="top">unusual and effective<br/>Nice use of the moon</td>', 'unusual and effectiveNice use of the moon', '2004-01-16 00:33:40.000000', NULL, 1),
(545464, 54343, 11078, '<td valign="top">very nice work<br/></td>', 'very nice work', '2004-01-16 00:35:07.000000', NULL, 1),
(545465, 54178, 11078, '<td valign="top">I love the colours and the use of light <br/>very effective<br/>nice work</td>', 'I love the colours and the use of light very effectivenice work', '2004-01-16 00:36:23.000000', NULL, 1),
(545466, 54206, 11078, '<td valign="top">This almost looks like an eye <br/>very creepy and unusual  nice work I am not so sure I like the shadow though<br/>7</td>', 'This almost looks like an eye very creepy and unusual  nice work I am not so sure I like the shadow though7', '2004-01-16 00:38:24.000000', NULL, 1),
(545467, 54728, 11078, '<td valign="top">nice I love the colours</td>', 'nice I love the colours', '2004-01-16 00:40:55.000000', NULL, 1),
(545469, 54773, 11078, '<td valign="top">how do you do a border like that? I like the way its done <br/>a superb image beautiful colour and tones</td>', 'how do you do a border like that? I like the way its done a superb image beautiful colour and tones', '2004-01-16 00:46:29.000000', NULL, 1),
(545470, 54716, 11078, '<td valign="top">very effective</td>', 'very effective', '2004-01-16 00:47:10.000000', NULL, 1),
(545471, 54534, 11078, '<td valign="top">very unusual  I thought this was a bit wierd at first but It is really very clever work<br/>I dont know how this is done though <br/>I think this will be in the top shots</td>', 'very unusual  I thought this was a bit wierd at first but It is really very clever workI dont know how this is done though I think this will be in the top shots', '2004-01-16 00:49:51.000000', NULL, 1),
(545472, 54730, 11078, '<td valign="top">i love windmills and you have taken a very interesting view of one</td>', 'i love windmills and you have taken a very interesting view of one', '2004-01-16 00:52:58.000000', NULL, 1),
(545473, 54766, 11078, '<td valign="top">very nice</td>', 'very nice', '2004-01-16 00:56:56.000000', NULL, 1),
(545554, 54542, 5534, '<td valign="top">Normally I don''t like these type of shots, but this is done well. Plus the colors of the sky adds a nice touch.</td>', 'Normally I don''t like these type of shots, but this is done well. Plus the colors of the sky adds a nice touch.', '2004-01-16 03:53:41.000000', NULL, 1),
(545556, 54464, 5534, '<td valign="top">Nice use of a slow shutter speed on this photo. Although I don''t really care for the angle of the shot and the distracting bright spots it''s a overall good photo. 7</td>', 'Nice use of a slow shutter speed on this photo. Although I don''t really care for the angle of the shot and the distracting bright spots it''s a overall good photo. 7', '2004-01-16 04:01:14.000000', NULL, 1),
(545645, 54477, 3540, '<td valign="top">It looks a bit like its running downhill from R to L.  Its busy, which does convey something about the photo, but leaves me looking for some focal point.  The size of the image is definitely not helping things.  This has a lot of potential, but as is, its not terribly strong</td>', 'It looks a bit like its running downhill from R to L.  Its busy, which does convey something about the photo, but leaves me looking for some focal point.  The size of the image is definitely not helping things.  This has a lot of potential, but as is, its not terribly strong', '2004-01-16 09:10:34.000000', NULL, 1),
(545650, 54767, 3540, '<td valign="top">Nicely done.  I like the 2 beams of light going up toward the sky.  Might be a little more exposed than I''d like to see it, but very very close.  Good work and good luck</td>', 'Nicely done.  I like the 2 beams of light going up toward the sky.  Might be a little more exposed than I''d like to see it, but very very close.  Good work and good luck', '2004-01-16 09:20:36.000000', NULL, 1),
(545662, 54776, 3540, '<td valign="top">I love the way the tree looks like its standing out of the photo.  Great job with the lighting and exposure of this shot.  Nice work - 9</td>', 'I love the way the tree looks like its standing out of the photo.  Great job with the lighting and exposure of this shot.  Nice work - 9', '2004-01-16 10:01:33.000000', NULL, 1),
(545667, 54530, 3540, '<td valign="top">Lots of noise and banding on this photo.  I like the idea a lot, just something wasn''t just right with the camera.  There are also a few hot spots and the crop is a little tight.  I don''t hate this photo honest... I see that there is a lot of potential with this photo.  At least enough to encourage you to go shoot it again, for what it''s worth.  Good luck!</td>', 'Lots of noise and banding on this photo.  I like the idea a lot, just something wasn''t just right with the camera.  There are also a few hot spots and the crop is a little tight.  I don''t hate this photo honest... I see that there is a lot of potential with this photo.  At least enough to encourage you to go shoot it again, for what it''s worth.  Good luck!', '2004-01-16 10:09:53.000000', NULL, 1),
(545835, 54338, 15535, '<td valign="top">where did you get that cat from? it is weird you should take it to the vet that is some weird cat LOL.</td>', 'where did you get that cat from? it is weird you should take it to the vet that is some weird cat LOL.', '2004-01-16 13:04:28.000000', NULL, 1),
(545865, 54565, 15703, '<td valign="top">A great angle on the old light-trails trick. The length of the trail is ideal for suggesting a ghost train has just passed through. The snow lifts the picture nicely, too.</td>', 'A great angle on the old light-trails trick. The length of the trail is ideal for suggesting a ghost train has just passed through. The snow lifts the picture nicely, too.', '2004-01-16 13:44:02.000000', NULL, 1),
(545870, 54542, 15703, '<td valign="top">I kept passing this shot by when viewing the thumbnails. Light trails have been done to death and I wasn''t going to viewyet another copy. But every time the thumbnails loaded, I kept catching myself looking first at this one, and finding the red, blue and white very appealing. As you can see, in the end I gave in and came for a fuller view. I love it a lot. The lights of the distant town, the curved road with plenty of powerful black visible. Yum!</td>', 'I kept passing this shot by when viewing the thumbnails. Light trails have been done to death and I wasn''t going to viewyet another copy. But every time the thumbnails loaded, I kept catching myself looking first at this one, and finding the red, blue and white very appealing. As you can see, in the end I gave in and came for a fuller view. I love it a lot. The lights of the distant town, the curved road with plenty of powerful black visible. Yum!', '2004-01-16 13:49:13.000000', NULL, 1),
(545874, 54624, 15703, '<td valign="top">I am not keen on funereal borders, but here it doesn''t especially detract since the shot itself is a dark one. I like this shot a lot.</td>', 'I am not keen on funereal borders, but here it doesn''t especially detract since the shot itself is a dark one. I like this shot a lot.', '2004-01-16 13:51:09.000000', NULL, 1),
(545917, 54703, 7628, '<td valign="top">I like to compare this to the other road with car shots in the challenge.  Here there is no blur of lights and no color, which is all the point in the other pics.  It has the same curves composition, but reaching to the skyline.  I like the balck and white and the slight gritty texture, not only looks like after dark, but feels like afterdark.  9</td>', 'I like to compare this to the other road with car shots in the challenge.  Here there is no blur of lights and no color, which is all the point in the other pics.  It has the same curves composition, but reaching to the skyline.  I like the balck and white and the slight gritty texture, not only looks like after dark, but feels like afterdark.  9', '2004-01-16 14:35:14.000000', NULL, 1),
(545918, 54599, 7628, '<td valign="top">wow.  this is surreal.  What wonderful blue color, what dramatic composition,  I like the gradient in the sky, and the sharp stars.  The texture of the sand/snow, and the dark tufts of grass. my fav. 10</td>', 'wow.  this is surreal.  What wonderful blue color, what dramatic composition,  I like the gradient in the sky, and the sharp stars.  The texture of the sand/snow, and the dark tufts of grass. my fav. 10', '2004-01-16 14:37:09.000000', NULL, 1),
(545919, 54542, 7628, '<td valign="top">A classic night time shot.  I like the sweep on the road up and to the left.  Wish that aiplane hadn''t gone across just then - it pulls my eyes a bit away from the lines of lights and the road.  I like the orange glow on the horizon. 8</td>', 'A classic night time shot.  I like the sweep on the road up and to the left.  Wish that aiplane hadn''t gone across just then - it pulls my eyes a bit away from the lines of lights and the road.  I like the orange glow on the horizon. 8', '2004-01-16 14:38:46.000000', NULL, 1),
(545922, 54477, 7628, '<td valign="top">Wish this were a bit bigger.  The colors and texture capture the feel of the city at night nicely.  The resolution isn;t so great, is this a crop out of a larger picture?</td>', 'Wish this were a bit bigger.  The colors and texture capture the feel of the city at night nicely.  The resolution isn;t so great, is this a crop out of a larger picture?', '2004-01-16 14:40:36.000000', NULL, 1),
(545923, 54613, 7628, '<td valign="top">cool effect with the smoke from the building illuminated and blown in the wind.</td>', 'cool effect with the smoke from the building illuminated and blown in the wind.', '2004-01-16 14:41:30.000000', NULL, 1),
(545924, 54717, 7628, '<td valign="top">Almost abstract.  The movement of the clouds/smoke makes a great background.  I like how bright the lights are, and the golden color.</td>', 'Almost abstract.  The movement of the clouds/smoke makes a great background.  I like how bright the lights are, and the golden color.', '2004-01-16 14:42:47.000000', NULL, 1),
(545927, 54514, 7628, '<td valign="top">Great colors and light, wish you could have gotten down a bit further and had the umbrellas come down into the picture, behind the men standing there.  But that is being a bit picky - it is a nice capture, a good feeling for the place and people.</td>', 'Great colors and light, wish you could have gotten down a bit further and had the umbrellas come down into the picture, behind the men standing there.  But that is being a bit picky - it is a nice capture, a good feeling for the place and people.', '2004-01-16 14:45:53.000000', NULL, 1),
(545929, 54627, 7628, '<td valign="top">Glorious!  So much darkness, but so much detail too.  The composition leads the eye so nicely up to that light, that is so bright and distinct. 10</td>', 'Glorious!  So much darkness, but so much detail too.  The composition leads the eye so nicely up to that light, that is so bright and distinct. 10', '2004-01-16 14:48:06.000000', NULL, 1),
(545940, 54527, 8860, '<td valign="top">Good angle and nice lighting make for a dynamic shot. Whites are a touch overexposed.</td>', 'Good angle and nice lighting make for a dynamic shot. Whites are a touch overexposed.', '2004-01-16 14:54:26.000000', NULL, 1),
(545943, 54542, 8860, '<td valign="top">Very clean light streaks shot indeed. Plane is slightly distracting but colours are good if a little oveersxposed in the whites.</td>', 'Very clean light streaks shot indeed. Plane is slightly distracting but colours are good if a little oveersxposed in the whites.', '2004-01-16 14:56:09.000000', NULL, 1),
(545948, 54313, 8860, '<td valign="top">Is this Mr D with his F717 on IR?  Anyway - very nice surreal vibe to this and the stars coming through help to add depth.</td>', 'Is this Mr D with his F717 on IR?  Anyway - very nice surreal vibe to this and the stars coming through help to add depth.', '2004-01-16 14:59:08.000000', NULL, 1),
(545970, 54336, 8860, '<td valign="top">This is a surprisingly nice shot for a scene that could be so boring - the art of a good photo. Very well composed, great lighting, lovely shadows and if anything it''s an effective use of materials if nothing more suited to the challenge was at hand. Well done. [8]</td>', 'This is a surprisingly nice shot for a scene that could be so boring - the art of a good photo. Very well composed, great lighting, lovely shadows and if anything it''s an effective use of materials if nothing more suited to the challenge was at hand. Well done. [8]', '2004-01-16 15:16:50.000000', NULL, 1),
(545972, 54599, 8860, '<td valign="top">Simply a wonderful image whose colour will match its ribbon. <br/> <br/>Well done an a really crisp, vibrant and mildly surreal looking shot. It\\\''s my absollute hands-down winner in this challenge and I''ll favourite this when the challenge is over. A victorious [10]</td>', 'Simply a wonderful image whose colour will match its ribbon.  Well done an a really crisp, vibrant and mildly surreal looking shot. It\\\''s my absollute hands-down winner in this challenge and I''ll favourite this when the challenge is over. A victorious [10]', '2004-01-16 15:17:37.000000', NULL, 1),
(545994, 54206, 15975, '<td valign="top">I like your photo, how did you take it?<br/>What is the thing that is at the left of the moon?<br/>It seems a reflexion</td>', 'I like your photo, how did you take it?What is the thing that is at the left of the moon?It seems a reflexion', '2004-01-16 16:21:48.000000', NULL, 1),
(546048, 54458, 6388, '<td valign="top">NIce.  looks to be a long exposure that ends up with a few blown out spots, especially the red sign on the right, and the tower on the left. (mine had exactly the same problem for this challenge :)). It''s a really fine line between overexposure and getting the building detail.  I think you did an admirable job of it.  Love the addition of the water.  Really low noise too, which is awesome.<br/>Pedro</td>', 'NIce.  looks to be a long exposure that ends up with a few blown out spots, especially the red sign on the right, and the tower on the left. (mine had exactly the same problem for this challenge :)). It''s a really fine line between overexposure and getting the building detail.  I think you did an admirable job of it.  Love the addition of the water.  Really low noise too, which is awesome.Pedro', '2004-01-16 18:12:55.000000', NULL, 1),
(546076, 53986, 8860, '<td valign="top">Serenely beautiful shot, gentle colours and soothing subject. Excellent. My second place. [9]</td>', 'Serenely beautiful shot, gentle colours and soothing subject. Excellent. My second place. [9]', '2004-01-16 18:35:50.000000', NULL, 1),
(546087, 54631, 16234, '<td valign="top">Excellent photograph!</td>', 'Excellent photograph!', '2004-01-16 18:52:46.000000', NULL, 1),
(546089, 54613, 2158, '<td valign="top">This shot is amazing.  <br/> <br/>Just wondering what is coming out of the top of some of those buildings.  It almost looks as though they are on fire.</td>', 'This shot is amazing.   Just wondering what is coming out of the top of some of those buildings.  It almost looks as though they are on fire.', '2004-01-16 18:54:52.000000', NULL, 1),
(546105, 54560, 6870, '<td valign="top">Very abstract and  very infinity! I like the colors and your ''natural'' composition. I''ll be interested to know what this is!</td>', 'Very abstract and  very infinity! I like the colors and your ''natural'' composition. I''ll be interested to know what this is!', '2004-01-16 19:51:20.000000', NULL, 1),
(546106, 54759, 6870, '<td valign="top">Nicely seen! I really enjoy the framing with the crag and the mountains. Lots of drama here!</td>', 'Nicely seen! I really enjoy the framing with the crag and the mountains. Lots of drama here!', '2004-01-16 19:52:07.000000', NULL, 1),
(546108, 54668, 6870, '<td valign="top">Very exciting shot. The sillhouette works very well, and the fact that smoke is the (indirect) source of light makes this very interesting.</td>', 'Very exciting shot. The sillhouette works very well, and the fact that smoke is the (indirect) source of light makes this very interesting.', '2004-01-16 19:53:02.000000', NULL, 1),
(546110, 54343, 6870, '<td valign="top">So THAT''S what landed out there in 1947! Now I know. I like the gradient color in the background here, and your point of view works well.</td>', 'So THAT''S what landed out there in 1947! Now I know. I like the gradient color in the background here, and your point of view works well.', '2004-01-16 19:54:25.000000', NULL, 1),
(546112, 54374, 6870, '<td valign="top">Such a dramatic, interesting shot! I do wish it were in focus--the trees, at least. But the light on the twisted branches is sooooo nice.</td>', 'Such a dramatic, interesting shot! I do wish it were in focus--the trees, at least. But the light on the twisted branches is sooooo nice.', '2004-01-16 19:55:13.000000', NULL, 1),
(546113, 54565, 6870, '<td valign="top">I like the blur a lot! There are lots of elements that detract from the train, but I do enjoy exploring the photo, too. That dark triangle in the foreground gets a lot of attention.</td>', 'I like the blur a lot! There are lots of elements that detract from the train, but I do enjoy exploring the photo, too. That dark triangle in the foreground gets a lot of attention.', '2004-01-16 19:56:32.000000', NULL, 1),
(546114, 54772, 6870, '<td valign="top">Fun composition. This looks like a sci-fi city scape of the future. I like the tones and colors.</td>', 'Fun composition. This looks like a sci-fi city scape of the future. I like the tones and colors.', '2004-01-16 19:57:14.000000', NULL, 1),
(546116, 54336, 6870, '<td valign="top">Very nice. This photo is quite subtle, but I really do like its sense of balance and how the shaft of light on the wall takes my eye around the image.</td>', 'Very nice. This photo is quite subtle, but I really do like its sense of balance and how the shaft of light on the wall takes my eye around the image.', '2004-01-16 19:58:09.000000', NULL, 1),
(546117, 54631, 6870, '<td valign="top">Nice model and lighting. I suppose it could be just a tad sharper, but this is marvelous composition. You capture the drama of the situation very well.</td>', 'Nice model and lighting. I suppose it could be just a tad sharper, but this is marvelous composition. You capture the drama of the situation very well.', '2004-01-16 19:59:09.000000', NULL, 1),
(546118, 54726, 6870, '<td valign="top">The city is lovely, and what I really enjoy is the sudden revelation that there are boats in front! That''s a nice surprise, so I like how the image works to do it.</td>', 'The city is lovely, and what I really enjoy is the sudden revelation that there are boats in front! That''s a nice surprise, so I like how the image works to do it.', '2004-01-16 20:00:20.000000', NULL, 1),
(546119, 53986, 6870, '<td valign="top">Super use of line. The misty rocks are very lovely, too. The hardest thing in photography is getting the horizon straight--and you do that, too!</td>', 'Super use of line. The misty rocks are very lovely, too. The hardest thing in photography is getting the horizon straight--and you do that, too!', '2004-01-16 20:01:18.000000', NULL, 1),
(546120, 54767, 6870, '<td valign="top">Very fantasy-land feel to this image. I like your vantage point here, and how the street lights make a  nice procession from left to right.</td>', 'Very fantasy-land feel to this image. I like your vantage point here, and how the street lights make a  nice procession from left to right.', '2004-01-16 20:02:08.000000', NULL, 1),
(546121, 54712, 6870, '<td valign="top">Looks like a lovely, cozy place. Nice composition--though have you tried a wider angle to get more lake? I love the reflection and darkness all around.</td>', 'Looks like a lovely, cozy place. Nice composition--though have you tried a wider angle to get more lake? I love the reflection and darkness all around.', '2004-01-16 20:03:14.000000', NULL, 1),
(546122, 54593, 6870, '<td valign="top">Just a bit grainy, but the symmetrical composition works well for me. I like the single figure walking in front. I''m very attracted to the large ''R''. It might be fun to get just a shot of that some day.</td>', 'Just a bit grainy, but the symmetrical composition works well for me. I like the single figure walking in front. I''m very attracted to the large ''R''. It might be fun to get just a shot of that some day.', '2004-01-16 20:04:35.000000', NULL, 1),
(546123, 54774, 6870, '<td valign="top">Looks nice with a retro-space age look to it. I like the colors and your emphasis of the lines and windows. I''m not sure the empty foreground does much, but this is an interesting image.</td>', 'Looks nice with a retro-space age look to it. I like the colors and your emphasis of the lines and windows. I''m not sure the empty foreground does much, but this is an interesting image.', '2004-01-16 20:06:03.000000', NULL, 1),
(546124, 54534, 6870, '<td valign="top">Very interesting effect. I''ll be anxious to know your technique for partial transparency. Composition is good, though I''m tempted to crop the sky just a little. The bright light just behind his head gets a lot of attention.</td>', 'Very interesting effect. I''ll be anxious to know your technique for partial transparency. Composition is good, though I''m tempted to crop the sky just a little. The bright light just behind his head gets a lot of attention.', '2004-01-16 20:07:31.000000', NULL, 1),
(546126, 54527, 6870, '<td valign="top">Very fun and unusual view of this landmark. I''m glad you didn''t try to get the whole structure all the way to the top. I like the crop--it makes it seem even taller. 9</td>', 'Very fun and unusual view of this landmark. I''m glad you didn''t try to get the whole structure all the way to the top. I like the crop--it makes it seem even taller. 9', '2004-01-16 20:08:31.000000', NULL, 1),
(546127, 54178, 6870, '<td valign="top">Fun and dramatic lighting! Nice random-looking composition.</td>', 'Fun and dramatic lighting! Nice random-looking composition.', '2004-01-16 20:09:03.000000', NULL, 1),
(546129, 54598, 11570, '<td valign="top">Nice twilight architectural shot just a pity that the sky appears so over cast. An 8</td>', 'Nice twilight architectural shot just a pity that the sky appears so over cast. An 8', '2004-01-16 20:10:01.000000', NULL, 1),
(546130, 54760, 6870, '<td valign="top">A capitol idea for a shot! It is almost symmetrical; you may consider tightening that up just a bit. I like your night lighting here.</td>', 'A capitol idea for a shot! It is almost symmetrical; you may consider tightening that up just a bit. I like your night lighting here.', '2004-01-16 20:10:57.000000', NULL, 1),
(546133, 54657, 11570, '<td valign="top">I like this there is a lot to \"see\" in this image but the strange thing is that my eye keeps getting drawn by the blue motorcycle, normally it is red that attracts the attention.  I wonder whther a very tight crop against the right hand side of the building would help?</td>', 'I like this there is a lot to \"see\" in this image but the strange thing is that my eye keeps getting drawn by the blue motorcycle, normally it is red that attracts the attention.  I wonder whther a very tight crop against the right hand side of the building would help?', '2004-01-16 20:13:12.000000', NULL, 1),
(546134, 54223, 6870, '<td valign="top">Lovely! The fountain may be just a tad bright, but the vantage point is very nice and dramatic!</td>', 'Lovely! The fountain may be just a tad bright, but the vantage point is very nice and dramatic!', '2004-01-16 20:13:22.000000', NULL, 1),
(546135, 54688, 6870, '<td valign="top">Very nice, mysterious image! I love your moody lighting. Super idea and well seen! 10</td>', 'Very nice, mysterious image! I love your moody lighting. Super idea and well seen! 10', '2004-01-16 20:13:59.000000', NULL, 1),
(546137, 54206, 6870, '<td valign="top">Very fun image. The lens flare of the moon really adds for me. Nice framing choice.</td>', 'Very fun image. The lens flare of the moon really adds for me. Nice framing choice.', '2004-01-16 20:14:40.000000', NULL, 1),
(546138, 54466, 11570, '<td valign="top">Hmmmmm!!!!  An atmospheric shot.<br/> <br/>If this was a candid then I can see why the subjects are "remote" but is set up then a tighter portrait image would be better.<br/> <br/>However, for this I would prefer a a crop of the left hand side putting the kissing couple on the thirds and losing all that dead space.</td>', 'Hmmmmm!!!!  An atmospheric shot. If this was a candid then I can see why the subjects are "remote" but is set up then a tighter portrait image would be better. However, for this I would prefer a a crop of the left hand side putting the kissing couple on the thirds and losing all that dead space.', '2004-01-16 20:16:34.000000', NULL, 1),
(546139, 54615, 6870, '<td valign="top">I don''t recognize this temple. I''ll be anxious to see which one it is. B/W is an interesting choice, since usually temples have such a lovely golden hue. I''ll trust you on that one. I love the drastic composition, too! 8</td>', 'I don''t recognize this temple. I''ll be anxious to see which one it is. B/W is an interesting choice, since usually temples have such a lovely golden hue. I''ll trust you on that one. I love the drastic composition, too! 8', '2004-01-16 20:16:49.000000', NULL, 1),
(546140, 54768, 6870, '<td valign="top">Really cool idea! The light is a bit bright for me, but I love what it does to the tree.</td>', 'Really cool idea! The light is a bit bright for me, but I love what it does to the tree.', '2004-01-16 20:17:21.000000', NULL, 1),
(546142, 54576, 6870, '<td valign="top">I wish it were in focus, but the composition is very effective with the moon in the upper left.</td>', 'I wish it were in focus, but the composition is very effective with the moon in the upper left.', '2004-01-16 20:17:54.000000', NULL, 1),
(546143, 54668, 11570, '<td valign="top">An intersting Duotone very well caught with the ciggie glowing. An 8</td>', 'An intersting Duotone very well caught with the ciggie glowing. An 8', '2004-01-16 20:18:29.000000', NULL, 1),
(546146, 54711, 11570, '<td valign="top">A nice "use" of lens flare.<br/> <br/>A little oddly it does look like the hot spot did not force the aperture closed as the tree on the right is sharp but the horizon seems a little OOF as if the aperture was what you might expect of an evening shot i.e. wide opne with narrow DOF.<br/> <br/>I look forward to seeing the details later.</td>', 'A nice "use" of lens flare. A little oddly it does look like the hot spot did not force the aperture closed as the tree on the right is sharp but the horizon seems a little OOF as if the aperture was what you might expect of an evening shot i.e. wide opne with narrow DOF. I look forward to seeing the details later.', '2004-01-16 20:22:19.000000', NULL, 1),
(546147, 54534, 11570, '<td valign="top">A long exposure an subject moved I suppose.  An interesting concept well executed An 8</td>', 'A long exposure an subject moved I suppose.  An interesting concept well executed An 8', '2004-01-16 20:23:27.000000', NULL, 1),
