(547443, 54599, 14193, '<td valign="top">Absolutely gorgeous, love this shot (9).</td>', 'Absolutely gorgeous, love this shot (9).', '2004-01-18 08:51:22.000000', NULL, 1),
(547446, 54605, 14193, '<td valign="top">Gotta get me a telescope! This looks great. (8)</td>', 'Gotta get me a telescope! This looks great. (8)', '2004-01-18 08:52:41.000000', NULL, 1),
(547450, 54725, 14193, '<td valign="top">Nice image. Subject is well lit, but maybe a bit harshly on the book itself. Unfortunately the cordless phone and other items in the foreground take away from the quaint feel of the pic and are a distraction. Otherwise very nice.</td>', 'Nice image. Subject is well lit, but maybe a bit harshly on the book itself. Unfortunately the cordless phone and other items in the foreground take away from the quaint feel of the pic and are a distraction. Otherwise very nice.', '2004-01-18 08:54:59.000000', NULL, 1),
(547454, 54178, 14193, '<td valign="top">I really like this picture. The colors on the tree combined with the dark blue background add a nice contrast to the scene. (7)</td>', 'I really like this picture. The colors on the tree combined with the dark blue background add a nice contrast to the scene. (7)', '2004-01-18 08:57:55.000000', NULL, 1),
(547462, 54665, 14193, '<td valign="top">I really like this picture. Great idea and your model did a good job of posing. (9)</td>', 'I really like this picture. Great idea and your model did a good job of posing. (9)', '2004-01-18 09:02:58.000000', NULL, 1),
(547472, 54624, 14614, '<td valign="top">I like the square frame and boarder.  Interesting sky and single focus subject. Well done 8</td>', 'I like the square frame and boarder.  Interesting sky and single focus subject. Well done 8', '2004-01-18 09:08:29.000000', NULL, 1),
(547478, 54458, 14614, '<td valign="top">The colors are set off well against the dark sky, nice blurring in the foreground</td>', 'The colors are set off well against the dark sky, nice blurring in the foreground', '2004-01-18 09:10:11.000000', NULL, 1),
(547480, 54742, 14614, '<td valign="top">I''m not sure what I''m looking at but it''s not abstract enough so I''m distracted by trying to figure out what I''m seeing.  The two-tone effect works.  The two lights provide good subjects but I think I would like them juxtaposed.</td>', 'I''m not sure what I''m looking at but it''s not abstract enough so I''m distracted by trying to figure out what I''m seeing.  The two-tone effect works.  The two lights provide good subjects but I think I would like them juxtaposed.', '2004-01-18 09:12:46.000000', NULL, 1),
(547485, 54223, 14614, '<td valign="top">THe fountain and tower sit at the "rule of thirds" points - this helps the composition.  I find the fountain too bright.  Simplifying the foreground would also help.</td>', 'THe fountain and tower sit at the "rule of thirds" points - this helps the composition.  I find the fountain too bright.  Simplifying the foreground would also help.', '2004-01-18 09:16:02.000000', NULL, 1),
(547486, 54730, 14614, '<td valign="top">You''ve posed the windmill at an interesting angle - I like the monochromatic, moody feel.  I would like it a smidge brighter.</td>', 'You''ve posed the windmill at an interesting angle - I like the monochromatic, moody feel.  I would like it a smidge brighter.', '2004-01-18 09:17:42.000000', NULL, 1),
(547488, 54770, 14614, '<td valign="top">This is a bit too dark for me to see the composition, sorry</td>', 'This is a bit too dark for me to see the composition, sorry', '2004-01-18 09:18:18.000000', NULL, 1),
(547490, 54561, 14614, '<td valign="top">Road leads the eye into the shot.  Would like to see one element in focus to give the viewer a focal point</td>', 'Road leads the eye into the shot.  Would like to see one element in focus to give the viewer a focal point', '2004-01-18 09:19:26.000000', NULL, 1),
(547494, 54614, 14614, '<td valign="top">Photo has an abstract quality.  I find it hard to pull the separate elements (tree, squiggle of light, bright spot in center, ghost, branches) to make a cohesive composition..</td>', 'Photo has an abstract quality.  I find it hard to pull the separate elements (tree, squiggle of light, bright spot in center, ghost, branches) to make a cohesive composition..', '2004-01-18 09:21:40.000000', NULL, 1),
(547497, 54639, 14614, '<td valign="top">So much of the left foreground is lost and the visible elements are out of focus so I don''t get pulled into the shot.</td>', 'So much of the left foreground is lost and the visible elements are out of focus so I don''t get pulled into the shot.', '2004-01-18 09:22:44.000000', NULL, 1),
(547498, 54575, 14614, '<td valign="top">I like the slow shutter effect on the water but that leaves the building fuzzy (would have liked it crisp or fuzzier - as is it distracts my eye too much)</td>', 'I like the slow shutter effect on the water but that leaves the building fuzzy (would have liked it crisp or fuzzier - as is it distracts my eye too much)', '2004-01-18 09:24:04.000000', NULL, 1),
(547499, 54726, 14614, '<td valign="top">Interesting sky line - would like to see more of the boats - needs to be better lit to see them.</td>', 'Interesting sky line - would like to see more of the boats - needs to be better lit to see them.', '2004-01-18 09:24:52.000000', NULL, 1),
(547501, 54645, 14614, '<td valign="top">Cropping helps direct my view and the lighter building in the foreground makes it clear which is your subject.  I don''t find the building interesting enough as the subject.  Seems a bit blurry - perhaps crisper would have captured me more.</td>', 'Cropping helps direct my view and the lighter building in the foreground makes it clear which is your subject.  I don''t find the building interesting enough as the subject.  Seems a bit blurry - perhaps crisper would have captured me more.', '2004-01-18 09:27:17.000000', NULL, 1),
(547503, 54276, 14614, '<td valign="top">Monocromatic pallet works well as a night shot.  Putting the tallest part of the building in the center weakens the composition.</td>', 'Monocromatic pallet works well as a night shot.  Putting the tallest part of the building in the center weakens the composition.', '2004-01-18 09:29:38.000000', NULL, 1),
(547504, 54726, 8637, '<td valign="top">Nice shot, but the foreground of the boats and dock distract from your theme which is the City at Night.  Pretty setting though.</td>', 'Nice shot, but the foreground of the boats and dock distract from your theme which is the City at Night.  Pretty setting though.', '2004-01-18 09:29:53.000000', NULL, 1),
(547505, 54477, 8637, '<td valign="top">Would have been better at larger size, and glare of car lights are a litle distracting.</td>', 'Would have been better at larger size, and glare of car lights are a litle distracting.', '2004-01-18 09:31:03.000000', NULL, 1),
(547506, 54635, 14614, '<td valign="top">Shooting the scene at night adds to the chaos and drama.  I''d like to see more of what''s going on (since your title highlights the journalistic aspect of your shot - I want to see more of what''s unfolding)</td>', 'Shooting the scene at night adds to the chaos and drama.  I''d like to see more of what''s going on (since your title highlights the journalistic aspect of your shot - I want to see more of what''s unfolding)', '2004-01-18 09:31:49.000000', NULL, 1),
(547507, 54711, 14614, '<td valign="top">A little less of the sun would be better.  Smoke is well lit,  The stacks need to be in focus and perhaps closer so they''re more of a powerful element in the shot.</td>', 'A little less of the sun would be better.  Smoke is well lit,  The stacks need to be in focus and perhaps closer so they''re more of a powerful element in the shot.', '2004-01-18 09:33:23.000000', NULL, 1),
(547508, 53986, 8637, '<td valign="top">I like the sheen on the rocks...unusual night shot.</td>', 'I like the sheen on the rocks...unusual night shot.', '2004-01-18 09:35:00.000000', NULL, 1),
(547509, 54764, 8637, '<td valign="top">Birds seem a little fuzzy..I like the clouds.</td>', 'Birds seem a little fuzzy..I like the clouds.', '2004-01-18 09:36:28.000000', NULL, 1),
(547514, 54743, 8637, '<td valign="top">Seems grainy..did you try "NeatImage" to correct?</td>', 'Seems grainy..did you try "NeatImage" to correct?', '2004-01-18 09:43:26.000000', NULL, 1),
(547522, 54776, 6532, '<td valign="top">I wish this was a bit brighter ..... still pretty awesome! 9</td>', 'I wish this was a bit brighter ..... still pretty awesome! 9', '2004-01-18 09:53:28.000000', NULL, 1),
(547525, 54605, 6532, '<td valign="top">N I C E !!! 10</td>', 'N I C E !!! 10', '2004-01-18 09:54:16.000000', NULL, 1),
(547537, 54523, 280, '<td valign="top">The starlight effect is too strong here.</td>', 'The starlight effect is too strong here.', '2004-01-18 10:16:08.000000', NULL, 1),
(547539, 54374, 280, '<td valign="top">The focus is too soft on the trees, try resting the camera against something.</td>', 'The focus is too soft on the trees, try resting the camera against something.', '2004-01-18 10:17:44.000000', NULL, 1),
(547540, 54768, 280, '<td valign="top">I don''t like the green hue, maybe yellow or even a pale blue would have suited the scene better?</td>', 'I don''t like the green hue, maybe yellow or even a pale blue would have suited the scene better?', '2004-01-18 10:20:05.000000', NULL, 1),
