(547543, 53986, 280, '<td valign="top">Beautiful colour and composition. 9</td>', 'Beautiful colour and composition. 9', '2004-01-18 10:24:47.000000', NULL, 1),
(547544, 54662, 280, '<td valign="top">NIce use of a long exposure to create the interesting cloud formation. 9</td>', 'NIce use of a long exposure to create the interesting cloud formation. 9', '2004-01-18 10:25:59.000000', NULL, 1),
(547547, 54627, 280, '<td valign="top">Not keen on the strong starlight efect you have here but a part from that it is a beautiful image.</td>', 'Not keen on the strong starlight efect you have here but a part from that it is a beautiful image.', '2004-01-18 10:35:48.000000', NULL, 1),
(547550, 54542, 280, '<td valign="top">Fantastic capture! I dont think I have seen this effect done this well on DPC before. 10</td>', 'Fantastic capture! I dont think I have seen this effect done this well on DPC before. 10', '2004-01-18 10:46:40.000000', NULL, 1),
(547585, 54627, 9411, '<td valign="top">Stunning image. Exceptionally well done. I find absolutely nothing to correct.  10</td>', 'Stunning image. Exceptionally well done. I find absolutely nothing to correct.  10', '2004-01-18 11:38:56.000000', NULL, 1),
(547586, 54607, 9411, '<td valign="top">Nicely done, Well thought out.  In a museum of design? A little post challenge spot editing and it''s perfect. 10</td>', 'Nicely done, Well thought out.  In a museum of design? A little post challenge spot editing and it''s perfect. 10', '2004-01-18 11:39:51.000000', NULL, 1),
(547587, 53986, 9411, '<td valign="top">Exceptional image. Well conceived and executed. 10</td>', 'Exceptional image. Well conceived and executed. 10', '2004-01-18 11:40:16.000000', NULL, 1),
