(547590, 54178, 9411, '<td valign="top">Wonderful colours. 9</td>', 'Wonderful colours. 9', '2004-01-18 11:41:26.000000', NULL, 1),
(547591, 54488, 9411, '<td valign="top">Excellent details, fun perspective. 9</td>', 'Excellent details, fun perspective. 9', '2004-01-18 11:42:12.000000', NULL, 1),
(547594, 54688, 9411, '<td valign="top">Very nice. Excellent use of available light. 10</td>', 'Very nice. Excellent use of available light. 10', '2004-01-18 11:42:37.000000', NULL, 1),
(547596, 54657, 9411, '<td valign="top">The angle is just a little off. Feels rather like one will tip over. Very nice image though.  8</td>', 'The angle is just a little off. Feels rather like one will tip over. Very nice image though.  8', '2004-01-18 11:43:26.000000', NULL, 1),
(547598, 54464, 9411, '<td valign="top">Very nice, unfortuante that the far edge of the falls are a tad overexposed. 8</td>', 'Very nice, unfortuante that the far edge of the falls are a tad overexposed. 8', '2004-01-18 11:44:15.000000', NULL, 1),
