(547604, 54767, 9411, '<td valign="top">I remember them well, spent many nights right down there. Well done, esp capturing the spot lights.<br/>9</td>', 'I remember them well, spent many nights right down there. Well done, esp capturing the spot lights.9', '2004-01-18 11:48:12.000000', NULL, 1),
(547669, 54662, 15403, '<td valign="top">I am struck by this photo.  I just keep coming back to it.</td>', 'I am struck by this photo.  I just keep coming back to it.', '2004-01-18 13:29:48.000000', NULL, 1),
(547670, 54719, 15403, '<td valign="top">awesome</td>', 'awesome', '2004-01-18 13:31:08.000000', NULL, 1),
