(547673, 54767, 15403, '<td valign="top">I''ve spent a lot of time in this place...</td>', 'I''ve spent a lot of time in this place...', '2004-01-18 13:32:16.000000', NULL, 1),
(547674, 54766, 15403, '<td valign="top">I really like the lighting</td>', 'I really like the lighting', '2004-01-18 13:32:50.000000', NULL, 1),
(547676, 54668, 15403, '<td valign="top">striking!  I would love to know if this was posed or candid?</td>', 'striking!  I would love to know if this was posed or candid?', '2004-01-18 13:34:50.000000', NULL, 1),
(547677, 54467, 15403, '<td valign="top">great concept</td>', 'great concept', '2004-01-18 13:36:36.000000', NULL, 1),
(547679, 54627, 15403, '<td valign="top">great shot...like a movie set.</td>', 'great shot...like a movie set.', '2004-01-18 13:38:53.000000', NULL, 1),
(547737, 54599, 14620, '<td valign="top">This shot reminds me of some great camping trips.  There''s nothing like the site of moonglow on the desert dunes.  This is beautiful!  I love how you were even able to capture the stars in the sky behind the dune.  Well Done!</td>', 'This shot reminds me of some great camping trips.  There''s nothing like the site of moonglow on the desert dunes.  This is beautiful!  I love how you were even able to capture the stars in the sky behind the dune.  Well Done!', '2004-01-18 15:59:55.000000', NULL, 1),
(547738, 54668, 14620, '<td valign="top">Great  colors, excellent silouhette!  The cigarette makes this interesting though, by adding the smoke and the red glow.  Very nice.</td>', 'Great  colors, excellent silouhette!  The cigarette makes this interesting though, by adding the smoke and the red glow.  Very nice.', '2004-01-18 16:00:24.000000', NULL, 1),
(547740, 54576, 3102, '<td valign="top">Would be nice if it were a bit sharper... I know how hard it is to get a good shot of our interplanetary neighbor... :)</td>', 'Would be nice if it were a bit sharper... I know how hard it is to get a good shot of our interplanetary neighbor... :)', '2004-01-18 16:15:53.000000', NULL, 1),
(547742, 54668, 3102, '<td valign="top">Definitely one of my favorites for this challenge!  I''m not a big fan of smoking, but the toning of the shot is great, and the blue haze gives a great feeling of a cold night.  The tiny bit of red in the cigarette itself is a nice touch.</td>', 'Definitely one of my favorites for this challenge!  I''m not a big fan of smoking, but the toning of the shot is great, and the blue haze gives a great feeling of a cold night.  The tiny bit of red in the cigarette itself is a nice touch.', '2004-01-18 16:18:20.000000', NULL, 1),
(547743, 54527, 3102, '<td valign="top">A nice perspective of a popular landmark!  I''m sure this will be top 10 material this week.</td>', 'A nice perspective of a popular landmark!  I''m sure this will be top 10 material this week.', '2004-01-18 16:19:15.000000', NULL, 1),
(547744, 54605, 3102, '<td valign="top">Nice and sharply done!  It might have been a little more dramatic to increase the contrast just a tad, but still a good job.</td>', 'Nice and sharply done!  It might have been a little more dramatic to increase the contrast just a tad, but still a good job.', '2004-01-18 16:20:59.000000', NULL, 1),
(547768, 54635, 772, '<td valign="top">City nights and city lights<br/>mayhem on the streets<br/>chaos, intensity<br/>people and sounds<br/>firemen working their beat</td>', 'City nights and city lightsmayhem on the streetschaos, intensitypeople and soundsfiremen working their beat', '2004-01-18 17:00:39.000000', NULL, 1),
(547769, 54354, 772, '<td valign="top">the station buzzes with people and sound<br/>as trains go whizzing by<br/>stop for me and take me home<br/>my request please don''t deny<br/>the people here are waiting<br/>for the cars with electric feet<br/>take us from this piercing cold<br/>back home into the heat</td>', 'the station buzzes with people and soundas trains go whizzing bystop for me and take me homemy request please don''t denythe people here are waitingfor the cars with electric feettake us from this piercing coldback home into the heat', '2004-01-18 17:03:24.000000', NULL, 1),
(547773, 54599, 772, '<td valign="top">there will be peace in the vally for me someday :)</td>', 'there will be peace in the vally for me someday :)', '2004-01-18 17:05:06.000000', NULL, 1),
(547775, 54688, 772, '<td valign="top">the path to hell is paved with good intentions :)</td>', 'the path to hell is paved with good intentions :)', '2004-01-18 17:08:28.000000', NULL, 1),
(547832, 54717, 6668, '<td valign="top">This is really a great shot, I love the lights and the movement of the smoke...nice work! 10<br/> <br/>Good luck...one of the best I''ve seen in this challenge!</td>', 'This is really a great shot, I love the lights and the movement of the smoke...nice work! 10 Good luck...one of the best I''ve seen in this challenge!', '2004-01-18 18:50:48.000000', NULL, 1),
